SELECT id as "id!", macro_id as "macro_id!", fusionauth_user_id as "fusionauth_user_id!", email_address as "email_address!", provider as "provider!: _", is_sync_active as "is_sync_active!", is_primary as "is_primary!", created_at as "created_at!", updated_at as "updated_at!" FROM ( SELECT el.id, el.macro_id, el.fusionauth_user_id, el.email_address, el.provider, el.is_sync_active, el.is_primary, el.created_at, el.updated_at FROM email_links el WHERE el.macro_id = $1 UNION SELECT el.id, el.macro_id, el.fusionauth_user_id, el.email_address, el.provider, el.is_sync_active, el.is_primary, el.created_at, el.updated_at FROM email_links el JOIN macro_user_links mul ON el.id = mul.link_id WHERE mul.primary_macro_id = $1 ) AS combined ORDER BY created_at DESC
